/**
 * _ma-6.mjs — mã THẬT của lab Chương 6 (sinh tự động bởi scratchpad/dbg/lab/ch6/tools/sinh-ma.mjs, 24/11/2026). Đã escape HTML.
 */
export const API = "// api.mjs — API LabFlow cho Chương 6 (node:http thuần). Chạy: node api.mjs  (cổng 41611, nginx đứng trước ở 41610)\n// SUA=\"body,ngay,id,reqid\" bật bản sửa từng lỗi; mặc định là bản có lỗi. HOA_DON = địa chỉ dịch vụ hoá đơn (Spring Boot).\nimport http from 'node:http';\nimport crypto from 'node:crypto';\nimport { AsyncLocalStorage } from 'node:async_hooks';\n\nconst SUA = new Set((process.env.SUA || '').split(',').filter(Boolean));\nconst PORT = Number(process.env.PORT || 41611);\nconst HOA_DON = process.env.HOA_DON || 'http://127.0.0.1:41612';\nconst ngu = (ms) =&gt; new Promise((r) =&gt; setTimeout(r, ms));\n\nconst phong = [{ id: 401, ten: 'Lab 401', choNgoi: 30 }, { id: 402, ten: 'Lab 402', choNgoi: 24 }];\nconst datCho = [{ id: 1, phong: 401, nguoiDat: 'SE1801', batDau: '2026-11-25T01:00:00.000Z' }];\nconst token = { 'sv-gia': { ten: 'SE1801', vaiTro: 'SV' }, 'gv-token': { ten: 'thayHung', vaiTro: 'GV' } };\n\n// ---- log JSON một dòng / sự kiện; reqId lấy từ AsyncLocalStorage nên hàm sâu bên trong cũng có ----\nconst ngCanh = new AsyncLocalStorage();\nfunction log(lvl, msg, them = {}) {\n  const rid = ngCanh.getStore()?.rid;\n  console.log(JSON.stringify({ t: new Date().toISOString(), lvl, svc: 'api-node', ...(rid ? { rid } : {}), msg, ...them }));\n}\nconst json = (res, code, body, extra = {}) =&gt; {\n  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', ...extra });\n  res.end(JSON.stringify(body));\n};\n\nasync function docBody(req) {\n  if (SUA.has('body')) {                         // ĐÚNG: gom Buffer rồi giải mã MỘT lần\n    const parts = []; for await (const c of req) parts.push(c);\n    return Buffer.concat(parts).toString('utf8');\n  }\n  let s = ''; for await (const c of req) s += c; // LỖI: mỗi chunk giải mã riêng ⇒ ký tự nhiều byte bị cắt đôi thành �\n  return s;\n}\n\nasync function goiHoaDon(id) {\n  const headers = SUA.has('reqid') ? { 'X-Request-Id': ngCanh.getStore().rid } : {};   // LỖI khi thiếu: không chuyền id sang dịch vụ sau\n  const r = await fetch(`${HOA_DON}/hoa-don/${id}`, { headers, signal: AbortSignal.timeout(2000) });\n  const text = await r.text();\n  log(r.ok ? 'info' : 'warn', 'hoa-don trả lời', { status: r.status, id });\n  if (SUA.has('id')) return { status: r.status, body: JSON.parse(text, (k, v, ctx) =&gt; (k === 'id' ? ctx.source : v)) }; // giữ nguyên chữ số\n  return { status: r.status, body: JSON.parse(text) };                                    // LỖI: số &gt; 2^53 bị làm tròn\n}\n\nconst server = http.createServer((req, res) =&gt; {\n  const rid = (SUA.has('reqid') &amp;&amp; req.headers['x-request-id']) || crypto.randomUUID().slice(0, 8);\n  ngCanh.run({ rid }, () =&gt; xuLy(req, res, rid).catch((e) =&gt; {\n    log('error', 'lỗi không bắt', { err: e.message, stack: e.stack.split('\\n').slice(0, 3).join(' | ') });\n    if (!res.headersSent) json(res, 500, { loi: 'Lỗi máy chủ', maThamChieu: rid });\n  }));\n});\n\nasync function xuLy(req, res, rid) {\n  const url = new URL(req.url, 'http://x');\n  const t0 = performance.now();\n  res.setHeader('X-Request-Id', rid);\n  res.on('finish', () =&gt; log('info', 'xong', { method: req.method, path: url.pathname, status: res.statusCode, ms: Math.round(performance.now() - t0) }));\n  res.on('close', () =&gt; { if (!res.writableFinished) log('warn', 'bên kia đóng kết nối trước khi trả lời xong', { rid, method: req.method, path: url.pathname, ms: Math.round(performance.now() - t0) }); });\n  const p = url.pathname;\n  let m;\n\n  if (req.method === 'GET' &amp;&amp; p === '/api/phong') return json(res, 200, phong);\n  if (req.method === 'GET' &amp;&amp; (m = p.match(/^\\/api\\/phong\\/(\\d+)$/))) {\n    const x = phong.find((q) =&gt; q.id === Number(m[1]));\n    return x ? json(res, 200, x) : json(res, 404, { loi: `Không có phòng ${m[1]}` });        // 404 vì DỮ LIỆU\n  }\n  if (p === '/api/toi' || p === '/api/bao-cao') {\n    const tk = (req.headers.authorization || '').replace(/^Bearer /, '');\n    const ai = token[tk];\n    if (!ai) return json(res, 401, { loi: 'Chưa đăng nhập hoặc token sai' }, { 'WWW-Authenticate': 'Bearer realm=\"labflow\"' });\n    if (p === '/api/bao-cao' &amp;&amp; ai.vaiTro !== 'GV') return json(res, 403, { loi: `Vai trò ${ai.vaiTro} không được xem báo cáo` });\n    return json(res, 200, p === '/api/toi' ? ai : { tuan: 47, luot: datCho.length });\n  }\n  if (req.method === 'GET' &amp;&amp; p === '/api/dat-cho') return json(res, 200, datCho);\n  if (req.method === 'POST' &amp;&amp; p === '/api/dat-cho') {\n    const raw = await docBody(req);\n    const ct = req.headers['content-type'] || '';\n    let b = {};\n    if (ct.startsWith('application/json')) {\n      try { b = JSON.parse(raw); } catch (e) { return json(res, 400, { loi: `JSON hỏng: ${e.message}` }); }\n    } else if (SUA.has('body')) return json(res, 415, { loi: `Cần Content-Type: application/json (nhận \"${ct || 'không có'}\")` });\n    if (!b.phong || !b.nguoiDat || !b.batDau) return json(res, 400, { loi: 'Thiếu trường phong/nguoiDat/batDau' });\n    if (SUA.has('ngay') &amp;&amp; !/(Z|[+-]\\d\\d:\\d\\d)$/.test(b.batDau)) return json(res, 400, { loi: 'batDau phải có múi giờ, ví dụ 2026-11-25T08:00:00+07:00' });\n    const batDau = new Date(b.batDau);                                                    // LỖI khi thiếu múi giờ: hiểu theo giờ của MÁY CHỦ\n    const moi = { id: datCho.length + 1, phong: b.phong, nguoiDat: b.nguoiDat, batDau: batDau.toISOString() };\n    datCho.push(moi);\n    log('info', 'tạo lượt', { nguoiDat: moi.nguoiDat, batDauNhan: b.batDau, batDauLuu: moi.batDau });\n    return json(res, 201, moi);\n  }\n  if (req.method === 'GET' &amp;&amp; (m = p.match(/^\\/api\\/hoa-don\\/(\\d+)(\\/pdf)?$/))) {\n    if (m[2]) {                                                                           // gọi sang Spring, Spring ném lỗi\n      const r = await fetch(`${HOA_DON}/hoa-don/${m[1]}/pdf`, { headers: SUA.has('reqid') ? { 'X-Request-Id': rid } : {} });\n      log('error', 'hoa-don lỗi khi in PDF', { status: r.status, id: m[1] });\n      return json(res, 502, { loi: 'Không in được hoá đơn, thử lại sau', maThamChieu: rid });\n    }\n    const r = await goiHoaDon(m[1]);\n    return json(res, r.status, r.body);\n  }\n  // ---- các tuyến dựng sẵn cho bài 6.1: mỗi tuyến làm hỏng một kiểu ----\n  if (p === '/api/cham') { await ngu(Number(url.searchParams.get('ms') || 5000)); return json(res, 200, { xong: true }); }\n  if (p === '/api/sap') { res.writeHead(200, { 'Content-Type': 'application/json' }); res.write('{\"phong\":['); return res.socket.destroy(); }\n  if (p === '/api/header-to') return json(res, 200, { ok: true }, { 'X-Debug-Trace': 'x'.repeat(16 * 1024) });\n  if (p === '/api/no') throw new Error('Cannot read properties of undefined (reading \\'choNgoi\\')');\n  return json(res, 404, { loi: `Không có tuyến ${req.method} ${p}` });                    // 404 vì TUYẾN\n}\n\nserver.listen(PORT, '127.0.0.1', () =&gt; log('info', `api-node nghe 127.0.0.1:${PORT}`, { sua: [...SUA] }));";
export const NGINX = "# nginx.conf — cổng vào LabFlow cho Chương 6 (container dbg-c6-nginx, --network host, chỉ nghe 127.0.0.1)\nworker_processes 1;\nerror_log /var/log/nginx/error.log warn;\nevents { worker_connections 256; }\nhttp {\n  # mỗi dòng access log có id của request + upstream đã trả gì, mất bao lâu\n  log_format chitiet '$time_iso8601 rid=$request_id \"$request\" $status '\n                     'rt=$request_time urt=$upstream_response_time us=$upstream_status ua=$upstream_addr';\n  access_log /var/log/nginx/access.log chitiet;\n  server_tokens on;\n\n  upstream api_node { server 127.0.0.1:41611; }\n\n  server {\n    listen 127.0.0.1:41610;\n    listen 127.0.0.1:41643 ssl;\n    server_name labflow.test;\n    ssl_certificate     /etc/nginx/tls/labflow.pem;\n    ssl_certificate_key /etc/nginx/tls/labflow.key;\n    client_max_body_size 64k;\n\n    location /api/ {\n      proxy_pass http://api_node;\n      proxy_set_header X-Request-Id $request_id;     # gắn id ở cổng vào, chuyền xuống app\n      add_header X-Request-Id $request_id always;    # và trả lại cho client\n      proxy_connect_timeout 2s;\n      proxy_read_timeout 3s;\n    }\n    location / { root /usr/share/nginx/html; }\n  }\n\n  # cổng thứ hai: cùng app nhưng chứng chỉ đã hết hạn (bài 6.1)\n  server {\n    listen 127.0.0.1:41644 ssl;\n    server_name labflow.test;\n    ssl_certificate     /etc/nginx/tls/het-han.pem;\n    ssl_certificate_key /etc/nginx/tls/labflow.key;\n    location / { return 200 \"ok\\n\"; }\n  }\n}";
export const JAVA = "package vn.labflow.hoadon;\n\nimport com.fasterxml.jackson.annotation.JsonFormat;\nimport jakarta.servlet.FilterChain;\nimport jakarta.servlet.ServletException;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.slf4j.MDC;\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.stereotype.Component;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.web.filter.OncePerRequestFilter;\nimport org.springframework.web.server.ResponseStatusException;\n\nimport java.io.IOException;\nimport java.math.BigDecimal;\nimport java.time.LocalDateTime;\nimport java.time.OffsetDateTime;\nimport java.util.Map;\nimport java.util.UUID;\n\n/** Dịch vụ hoá đơn của LabFlow (Chương 6): id kiểu snowflake (&gt; 2^53), tiền BigDecimal, giờ có và không có múi giờ. */\n@SpringBootApplication\npublic class HoaDonApp {\n  public static void main(String[] args) { SpringApplication.run(HoaDonApp.class, args); }\n}\n\nrecord HoaDon(Long id, String khach, BigDecimal tong, LocalDateTime taoLuc, OffsetDateTime hanTra) {}\n/** Bản v2: id gửi đi dạng CHUỖI — cùng cách Twitter thêm trường id_str năm 2010. */\nrecord HoaDonV2(@JsonFormat(shape = JsonFormat.Shape.STRING) Long id, String khach, BigDecimal tong, OffsetDateTime hanTra) {}\nrecord TaoHoaDon(String khach, BigDecimal tong, LocalDateTime hanTra) {}\n\n@RestController\nclass HoaDonController {\n  private static final Logger log = LoggerFactory.getLogger(HoaDonController.class);\n  private static final Map&lt;Long, HoaDon&gt; DB = Map.of(\n      1864276489217638401L, new HoaDon(1864276489217638401L, \"SE1801\", new BigDecimal(\"125000.50\"),\n          LocalDateTime.parse(\"2026-11-24T08:30:00\"), OffsetDateTime.parse(\"2026-12-01T17:00:00+07:00\")));\n\n  @GetMapping(\"/hoa-don/{id}\")\n  HoaDon xem(@PathVariable long id) {\n    HoaDon h = DB.get(id);\n    if (h == null) { log.warn(\"không có hoá đơn id={}\", id); throw new ResponseStatusException(HttpStatus.NOT_FOUND, \"Không có hoá đơn \" + id); }\n    return h;\n  }\n\n  @GetMapping(\"/v2/hoa-don/{id}\")\n  HoaDonV2 xemV2(@PathVariable long id) { HoaDon h = xem(id); return new HoaDonV2(h.id(), h.khach(), h.tong(), h.hanTra()); }\n\n  @GetMapping(\"/hoa-don/{id}/pdf\")\n  String pdf(@PathVariable long id) {\n    log.info(\"in PDF hoá đơn id={}\", id);\n    throw new IllegalStateException(\"Mẫu PDF thiếu phông chữ: /app/fonts/BeVietnamPro.ttf\");\n  }\n\n  @PostMapping(\"/hoa-don\")\n  TaoHoaDon tao(@RequestBody TaoHoaDon body) { log.info(\"nhận {}\", body); return body; }\n}\n\n/** BẢN SỬA (bật khi biến môi trường SUA chứa \"reqid\"): bắt lỗi TRONG lúc MDC còn id, ghi log kèm id, trả 500 có mã tham chiếu. */\n@RestControllerAdvice\n@org.springframework.boot.autoconfigure.condition.ConditionalOnExpression(\"'${SUA:}'.contains('reqid')\")\nclass LoiToanCuc {\n  private static final Logger log = LoggerFactory.getLogger(LoiToanCuc.class);\n  @ExceptionHandler(Exception.class)\n  org.springframework.http.ResponseEntity&lt;Map&lt;String, String&gt;&gt; loi(Exception e, HttpServletRequest req) {\n    log.error(\"lỗi không bắt ở {} {}\", req.getMethod(), req.getRequestURI(), e);\n    return org.springframework.http.ResponseEntity.status(500).body(Map.of(\"loi\", \"Lỗi máy chủ\", \"maThamChieu\", MDC.get(\"rid\")));\n  }\n}\n\n/** Gắn id cho mỗi request: lấy X-Request-Id nếu cổng vào đã gắn, không có thì tự sinh; đưa vào MDC để MỌI dòng log có id. */\n@Component\nclass RidFilter extends OncePerRequestFilter {\n  private static final Logger log = LoggerFactory.getLogger(RidFilter.class);\n  @Override\n  protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain) throws ServletException, IOException {\n    String rid = req.getHeader(\"X-Request-Id\");\n    if (rid == null || rid.isBlank()) rid = UUID.randomUUID().toString().substring(0, 8);\n    MDC.put(\"rid\", rid);\n    res.setHeader(\"X-Request-Id\", rid);\n    long t0 = System.nanoTime();\n    try { chain.doFilter(req, res); }\n    finally {\n      log.info(\"xong {} {} {} {}ms\", req.getMethod(), req.getRequestURI(), res.getStatus(), (System.nanoTime() - t0) / 1_000_000);\n      MDC.remove(\"rid\");\n    }\n  }\n}";
export const JAVA_PROPS = "server.address=127.0.0.1\nserver.port=41612\nspring.main.banner-mode=off\nlogging.pattern.console=%d{HH:mm:ss.SSS} %5p [hoa-don] rid=%X{rid:--} %logger{0} : %m%n\nlogging.level.org.springframework=WARN";
export const CHAY = "#!/bin/bash\n# chay.sh — dựng cổng vào nginx (container dbg-c6-nginx) + API Node (tiến trình, PID ở api.pid).\n# Gọi: env SUA=... TZ=UTC bash chay.sh      (TZ của API = giờ máy chủ; máy chủ thật thường là UTC)\ncd /tmp/dbg-lab/ch6\nmkdir -p log html\n[ -f html/index.html ] || echo '&lt;h1&gt;LabFlow&lt;/h1&gt;' &gt; html/index.html\nif ! docker ps --format '{{.Names}}' | grep -qx dbg-c6-nginx; then\n  docker rm -f dbg-c6-nginx &gt;/dev/null 2&gt;&amp;1\n  docker run -d --name dbg-c6-nginx --network host \\\n    -v \"$PWD/nginx/${CONF:-nginx.conf}:/etc/nginx/nginx.conf:ro\" -v \"$PWD/nginx/tls:/etc/nginx/tls:ro\" \\\n    -v \"$PWD/html:/usr/share/nginx/html:ro\" -v \"$PWD/log:/var/log/nginx\" nginx:1.27-alpine &gt;/dev/null\nfi\n[ -f api.pid ] &amp;&amp; kill \"$(cat api.pid)\" 2&gt;/dev/null; sleep 0.3\nTZ=\"${TZ:-UTC}\" node api/api.mjs &gt;&gt; log/api.log 2&gt;&amp;1 &amp; echo $! &gt; api.pid\nfor i in $(seq 1 50); do curl -sf -o /dev/null 127.0.0.1:41611/api/phong &amp;&amp; break; sleep 0.2; done\necho \"chạy: nginx $(docker inspect -f '{{.State.Status}}' dbg-c6-nginx), api pid $(cat api.pid)\"";
export const CHAY_JAVA = "#!/bin/bash\n# chay-java.sh — chạy dịch vụ hoá đơn (Spring Boot 4.1.1) ở 127.0.0.1:41612, PID ở java.pid, log ở log/java.log\ncd /tmp/dbg-lab/ch6\n[ -f java.pid ] &amp;&amp; kill \"$(cat java.pid)\" 2&gt;/dev/null; sleep 0.5\n: &gt; log/java.log\n(cd java &amp;&amp; exec java -Duser.timezone=\"${JTZ:-UTC}\" -cp target/classes:'target/lib/*' vn.labflow.hoadon.HoaDonApp) &gt;&gt; log/java.log 2&gt;&amp;1 &amp; echo $! &gt; java.pid\nfor i in $(seq 1 60); do grep -q 'Started HoaDonApp' log/java.log &amp;&amp; break; sleep 0.5; done\necho \"java pid $(cat java.pid)\"";
export const GUI_CAT_DOI = "// gui-cat-doi.mjs — gửi JSON có tiếng Việt thành HAI gói TCP, cắt đúng giữa một ký tự UTF-8 nhiều byte\n// (đời thật: body lớn, mạng chậm, proxy chia chunk — server nhận nhiều chunk là chuyện thường)\nimport http from 'node:http';\nconst body = Buffer.from(JSON.stringify({ phong: 401, nguoiDat: 'Nguyễn Thị Hương', batDau: '2026-11-25T08:00:00+07:00' }));\nconst cat = body.indexOf(Buffer.from('ễ')) + 1;            // 'ễ' = 3 byte e1 bb 85 — cắt sau byte đầu\nconsole.log(`body ${body.length} byte, cắt ở byte ${cat}: …${body.subarray(cat - 5, cat).toString('hex')} | ${body.subarray(cat, cat + 4).toString('hex')}…`);\nconst req = http.request({ host: '127.0.0.1', port: Number(process.argv[2] || 41611), path: '/api/dat-cho', method: 'POST',\n  headers: { 'Content-Type': 'application/json', 'Content-Length': body.length } }, (res) =&gt; {\n  let s = []; res.on('data', (c) =&gt; s.push(c)); res.on('end', () =&gt; console.log(res.statusCode, Buffer.concat(s).toString()));\n});\nreq.write(body.subarray(0, cat));\nsetTimeout(() =&gt; req.end(body.subarray(cat)), 50);";
export const NODE_TLS = "// node-tls.mjs — Node gọi HTTPS tới cổng 41643 (chứng chỉ do \"LabFlow Dev CA\" ký). Tên labflow.test trỏ về 127.0.0.1 bằng lookup riêng.\nimport https from 'node:https';\nconst lookup = (h, o, cb) =&gt; (o.all ? cb(null, [{ address: '127.0.0.1', family: 4 }]) : cb(null, '127.0.0.1', 4));\nhttps.get({ host: 'labflow.test', port: 41643, path: '/api/phong', lookup }, (r) =&gt; {\n  let s = ''; r.on('data', (c) =&gt; (s += c)); r.on('end', () =&gt; console.log(r.statusCode, s));\n}).on('error', (e) =&gt; console.log(`${e.code}: ${e.message}`));";
export const L_API = "// lab/api.mjs — API của Lab 6.5 (node:http, 127.0.0.1:41621; nginx ở 41620 phục vụ web + chuyển /api/ vào đây)\n// Máy chủ chạy TZ=UTC như máy chủ thật. Log JSON một dòng / request, có rid do nginx gắn.\nimport http from 'node:http';\n\nconst datCho = [\n  { id: 1, phong: 401, nguoiDat: 'SE1801', batDau: '2026-11-25T01:00:00.000Z', ghiChu: '' },\n  { id: 2, phong: 402, nguoiDat: 'SE1802', batDau: '2026-11-25T06:00:00.000Z', ghiChu: 'mang theo Arduino' },\n];\nconst log = (o) =&gt; console.log(JSON.stringify({ t: new Date().toISOString(), ...o }));\nconst json = (res, code, body) =&gt; { res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(body)); };\nasync function docJson(req) {\n  const parts = []; for await (const c of req) parts.push(c);\n  const raw = Buffer.concat(parts).toString('utf8');\n  if (!(req.headers['content-type'] || '').startsWith('application/json')) return {};   // không phải JSON thì coi như rỗng\n  return JSON.parse(raw || '{}');\n}\n\nhttp.createServer(async (req, res) =&gt; {\n  const p = new URL(req.url, 'http://x').pathname;\n  const rid = req.headers['x-request-id'] || '-';\n  res.on('finish', () =&gt; log({ rid, method: req.method, path: p, status: res.statusCode, ct: req.headers['content-type'] || null }));\n  let m;\n  try {\n    if (req.method === 'GET' &amp;&amp; p === '/api/dat-cho') return json(res, 200, datCho);\n    if (req.method === 'POST' &amp;&amp; p === '/api/dat-cho') {\n      const b = await docJson(req);\n      if (!b.phong || !b.nguoiDat || !b.batDau) return json(res, 400, { loi: 'Thiếu trường phong/nguoiDat/batDau' });\n      const moi = { id: datCho.length + 1, phong: Number(b.phong), nguoiDat: b.nguoiDat, batDau: new Date(b.batDau).toISOString(), ghiChu: '' };\n      datCho.push(moi);\n      return json(res, 201, moi);\n    }\n    if ((m = p.match(/^\\/api\\/dat-cho\\/(\\d+)\\/ghi-chu$/))) {\n      const d = datCho.find((x) =&gt; x.id === Number(m[1]));\n      if (!d) return json(res, 404, { loi: `Không có lượt ${m[1]}` });\n      if (req.method === 'GET') return json(res, 200, { id: d.id, ghiChu: d.ghiChu });\n      if (req.method === 'POST') { const b = await docJson(req); d.ghiChu = String(b.ghiChu ?? ''); return json(res, 200, { id: d.id, ghiChu: d.ghiChu }); }\n    }\n    return json(res, 404, { loi: `Không có tuyến ${req.method} ${p}` });\n  } catch (e) {\n    log({ rid, lvl: 'error', err: e.message });\n    return json(res, 500, { loi: 'Lỗi máy chủ', maThamChieu: rid });\n  }\n}).listen(41621, '127.0.0.1', () =&gt; log({ msg: 'lab api 127.0.0.1:41621', tz: Intl.DateTimeFormat().resolvedOptions().timeZone }));";
export const L_APP = "// web/app.js — giao diện Lab 6.5 (JS thuần, không build). Cùng origin với API qua nginx 41620.\nconst API = '/api';\nconst $ = (s) =&gt; document.querySelector(s);\nconst tb = (s, loi = false) =&gt; { $('#tb').textContent = s; $('#tb').className = loi ? 'loi' : 'ok'; };\n\n// \"thống kê lượt xem\" do một bạn khác thêm: mỗi lần mở trang ghi một cookie mới, không bao giờ xoá\nfunction ghiLuotXem() {\n  const n = Number(localStorage.getItem('lf_n') || 0) + 1;\n  localStorage.setItem('lf_n', String(n));\n  document.cookie = `_lf_v${n}=${Date.now()}.${crypto.randomUUID()}; path=/; max-age=31536000`;\n}\n\nasync function taiLich() {\n  const r = await fetch(`${API}/dat-cho`);\n  if (!r.ok) return tb(`Không tải được lịch (${r.status})`, true);\n  const ds = await r.json();\n  $('#ds').innerHTML = ds.map((d) =&gt; `&lt;li data-id=\"${d.id}\"&gt;#${d.id} Lab ${d.phong} — ${new Date(d.batDau).toLocaleString('vi-VN')} — ${d.nguoiDat}` +\n    ` &lt;button class=\"gc\"&gt;Ghi chú&lt;/button&gt; &lt;span class=\"ghi\"&gt;${d.ghiChu}&lt;/span&gt;&lt;/li&gt;`).join('');\n}\n\nasync function datLuot(e) {\n  e.preventDefault();\n  const d = { phong: $('#phong').value, nguoiDat: $('#ten').value, batDau: $('#gio').value };   // gio: &lt;input type=\"datetime-local\"&gt;\n  const r = await fetch(`${API}/dat-cho`, { method: 'POST', body: JSON.stringify(d) });\n  const kq = await r.json();\n  if (!r.ok) return tb(`Lỗi: ${kq.loi}`, true);\n  tb(`Đã đặt lượt #${kq.id}`); taiLich();\n}\n\nasync function luuGhiChu(id, ghiChu) {\n  const r = await fetch(`${API}/dat-cho/${id}/ghi-chu/`, {\n    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ghiChu }),\n  });\n  if (!r.ok) return tb(`Lỗi lưu ghi chú (${r.status})`, true);\n  tb(`Đã lưu ghi chú cho lượt #${id}`); taiLich();\n}\n\nghiLuotXem();\n$('#form').addEventListener('submit', datLuot);\n$('#ds').addEventListener('click', (e) =&gt; {\n  if (!e.target.matches('.gc')) return;\n  const id = e.target.closest('li').dataset.id;\n  const ghiChu = prompt('Ghi chú cho lượt #' + id) ?? '';\n  luuGhiChu(id, ghiChu);\n});\ntaiLich();";
export const L_HTML = "&lt;!doctype html&gt;\n&lt;html lang=\"vi\"&gt;&lt;head&gt;&lt;meta charset=\"utf-8\"&gt;&lt;title&gt;LabFlow — Đặt phòng lab&lt;/title&gt;\n&lt;style&gt;body{font:16px system-ui;margin:2rem}.loi{color:#b00}.ok{color:#070}li{margin:.3rem 0}&lt;/style&gt;&lt;/head&gt;\n&lt;body&gt;\n&lt;h1&gt;LabFlow — Đặt phòng lab&lt;/h1&gt;\n&lt;form id=\"form\"&gt;\n  &lt;select id=\"phong\"&gt;&lt;option value=\"401\"&gt;Lab 401&lt;/option&gt;&lt;option value=\"402\"&gt;Lab 402&lt;/option&gt;&lt;/select&gt;\n  &lt;input id=\"ten\" placeholder=\"Mã SV\" value=\"SE1809\"&gt;\n  &lt;input id=\"gio\" type=\"datetime-local\" value=\"2026-11-26T08:00\"&gt;\n  &lt;button&gt;Đặt lượt&lt;/button&gt;\n&lt;/form&gt;\n&lt;p id=\"tb\"&gt;&lt;/p&gt;\n&lt;ul id=\"ds\"&gt;&lt;/ul&gt;\n&lt;script src=\"/app.js\"&gt;&lt;/script&gt;\n&lt;/body&gt;&lt;/html&gt;";
export const L_NGINX = "# lab/nginx.conf — web tĩnh + /api/ (container dbg-c6-lab, --network host, 127.0.0.1:41620)\nworker_processes 1;\nevents { worker_connections 256; }\nhttp {\n  include /etc/nginx/mime.types;\n  log_format chitiet '$time_iso8601 rid=$request_id \"$request\" $status ct=\"$content_type\"';\n  access_log /var/log/nginx/access.log chitiet;\n  error_log /var/log/nginx/error.log info;   # info: mới thấy dòng \"client sent too long header line\"\n  server {\n    listen 127.0.0.1:41620;\n    # quy tắc \"bỏ dấu / cuối URL cho đẹp SEO\" chép từ cấu hình trang giới thiệu\n    rewrite ^/(.+)/$ /$1 permanent;\n    location /api/ {\n      proxy_pass http://127.0.0.1:41621;\n      proxy_set_header X-Request-Id $request_id;\n    }\n    location / { root /usr/share/nginx/html; }\n  }\n}";
export const L_CHAY = "#!/bin/bash\n# lab/chay.sh — chạy Lab 6.5: nginx (container dbg-c6-lab, cổng 127.0.0.1:41620) + API (TZ=UTC, 127.0.0.1:41621)\ncd \"$(dirname \"$0\")\"\nmkdir -p log\n[ -f api.pid ] &amp;&amp; kill \"$(cat api.pid)\" 2&gt;/dev/null; sleep 0.3\ndocker rm -f dbg-c6-lab &gt;/dev/null 2&gt;&amp;1\ndocker run -d --name dbg-c6-lab --network host -v \"$PWD/nginx.conf:/etc/nginx/nginx.conf:ro\" \\\n  -v \"$PWD/web:/usr/share/nginx/html:ro\" -v \"$PWD/log:/var/log/nginx\" nginx:1.27-alpine &gt;/dev/null\nTZ=UTC node api.mjs &gt; log/api.log 2&gt;&amp;1 &amp; echo $! &gt; api.pid\nfor i in $(seq 1 50); do curl -sf -o /dev/null 127.0.0.1:41620/api/dat-cho &amp;&amp; break; sleep 0.2; done\necho \"Lab 6.5: mở http://localhost:41620  (api pid $(cat api.pid))\"";
export const L_DIFF = "diff --color -ru -x log -x '*.pid' lab/api.mjs lab-sua/api.mjs\n--- lab/api.mjs\t2026-11-24 05:23:43.723996579 +0700\n+++ lab-sua/api.mjs\t2026-11-24 05:24:52.882893423 +0700\n@@ -11,7 +11,9 @@\n async function docJson(req) {\n   const parts = []; for await (const c of req) parts.push(c);\n   const raw = Buffer.concat(parts).toString('utf8');\n-  if (!(req.headers['content-type'] || '').startsWith('application/json')) return {};   // không phải JSON thì coi như rỗng\n+  if (!(req.headers['content-type'] || '').startsWith('application/json')) {             // BUG-601: nói thẳng, đừng giả vờ body rỗng\n+    const e = new Error(`Cần Content-Type: application/json (nhận \"${req.headers['content-type'] || 'không có'}\")`); e.status = 415; throw e;\n+  }\n   return JSON.parse(raw || '{}');\n }\n \n@@ -25,6 +27,7 @@\n     if (req.method === 'POST' &amp;&amp; p === '/api/dat-cho') {\n       const b = await docJson(req);\n       if (!b.phong || !b.nguoiDat || !b.batDau) return json(res, 400, { loi: 'Thiếu trường phong/nguoiDat/batDau' });\n+      if (!/(Z|[+-]\\d\\d:\\d\\d)$/.test(b.batDau)) return json(res, 400, { loi: 'batDau phải có múi giờ (Z hoặc +07:00)' });   // BUG-602\n       const moi = { id: datCho.length + 1, phong: Number(b.phong), nguoiDat: b.nguoiDat, batDau: new Date(b.batDau).toISOString(), ghiChu: '' };\n       datCho.push(moi);\n       return json(res, 201, moi);\n@@ -37,6 +40,7 @@\n     }\n     return json(res, 404, { loi: `Không có tuyến ${req.method} ${p}` });\n   } catch (e) {\n+    if (e.status) return json(res, e.status, { loi: e.message });\n     log({ rid, lvl: 'error', err: e.message });\n     return json(res, 500, { loi: 'Lỗi máy chủ', maThamChieu: rid });\n   }\ndiff --color -ru -x log -x '*.pid' lab/nginx.conf lab-sua/nginx.conf\n--- lab/nginx.conf\t2026-11-24 05:24:52.885906249 +0700\n+++ lab-sua/nginx.conf\t2026-11-24 05:24:52.882944174 +0700\n@@ -8,12 +8,15 @@\n   error_log /var/log/nginx/error.log info;   # info: mới thấy dòng \"client sent too long header line\"\n   server {\n     listen 127.0.0.1:41620;\n-    # quy tắc \"bỏ dấu / cuối URL cho đẹp SEO\" chép từ cấu hình trang giới thiệu\n-    rewrite ^/(.+)/$ /$1 permanent;\n+    # BUG-604 (tạm 2 tuần): người dùng cũ đang mang ~10 KB cookie; cho qua để app.js mới dọn được, rồi trả về mặc định 4 8k\n+    large_client_header_buffers 4 16k;\n     location /api/ {\n       proxy_pass http://127.0.0.1:41621;\n       proxy_set_header X-Request-Id $request_id;\n     }\n-    location / { root /usr/share/nginx/html; }\n+    location / {\n+      rewrite ^/(.+)/$ /$1 permanent;     # BUG-603: quy tắc SEO chỉ áp cho trang, KHÔNG cho /api/\n+      root /usr/share/nginx/html;\n+    }\n   }\n }\ndiff --color -ru -x log -x '*.pid' lab/web/app.js lab-sua/web/app.js\n--- lab/web/app.js\t2026-11-24 05:23:43.730997020 +0700\n+++ lab-sua/web/app.js\t2026-11-24 05:24:52.882829699 +0700\n@@ -3,11 +3,14 @@\n const $ = (s) =&gt; document.querySelector(s);\n const tb = (s, loi = false) =&gt; { $('#tb').textContent = s; $('#tb').className = loi ? 'loi' : 'ok'; };\n \n-// \"thống kê lượt xem\" do một bạn khác thêm: mỗi lần mở trang ghi một cookie mới, không bao giờ xoá\n+// BUG-604: đếm lượt xem trong localStorage (không đi theo request nào) + dọn các cookie _lf_v* cũ đã lỡ ghi\n function ghiLuotXem() {\n   const n = Number(localStorage.getItem('lf_n') || 0) + 1;\n   localStorage.setItem('lf_n', String(n));\n-  document.cookie = `_lf_v${n}=${Date.now()}.${crypto.randomUUID()}; path=/; max-age=31536000`;\n+  for (const c of document.cookie.split('; ')) {\n+    const ten = c.split('=')[0];\n+    if (/^_lf_v\\d+$/.test(ten)) document.cookie = `${ten}=; path=/; max-age=0`;\n+  }\n }\n \n async function taiLich() {\n@@ -20,15 +23,17 @@\n \n async function datLuot(e) {\n   e.preventDefault();\n-  const d = { phong: $('#phong').value, nguoiDat: $('#ten').value, batDau: $('#gio').value };   // gio: &lt;input type=\"datetime-local\"&gt;\n-  const r = await fetch(`${API}/dat-cho`, { method: 'POST', body: JSON.stringify(d) });\n+  // BUG-602: datetime-local không có múi giờ ⇒ đổi sang ISO có Z theo giờ của NGƯỜI DÙNG trước khi gửi\n+  const d = { phong: Number($('#phong').value), nguoiDat: $('#ten').value, batDau: new Date($('#gio').value).toISOString() };\n+  // BUG-601: body là chuỗi ⇒ fetch tự đặt text/plain; phải nói rõ là JSON\n+  const r = await fetch(`${API}/dat-cho`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(d) });\n   const kq = await r.json();\n   if (!r.ok) return tb(`Lỗi: ${kq.loi}`, true);\n   tb(`Đã đặt lượt #${kq.id}`); taiLich();\n }\n \n async function luuGhiChu(id, ghiChu) {\n-  const r = await fetch(`${API}/dat-cho/${id}/ghi-chu/`, {\n+  const r = await fetch(`${API}/dat-cho/${id}/ghi-chu`, {          // BUG-603: không có / cuối\n     method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ghiChu }),\n   });\n   if (!r.ok) return tb(`Lỗi lưu ghi chú (${r.status})`, true);";
export const L_KIEM = "// lab6.mjs — kiểm tự động Lab 6.5 bằng Chrome thật (headless, CDP). Người dùng ở Việt Nam (timezone Asia/Ho_Chi_Minh).\n// In như bảng Network của DevTools: method, URL, status, header gửi đi đáng chú ý. Cuối cùng: ĐẠT/CHƯA cho từng ticket.\n// Chạy: node tools/lab6.mjs [cổng=41620]\nimport { moTrinhDuyet, ngu } from './mo.mjs';\nconst PORT = process.argv[2] || 41620;\nconst GOC = `http://localhost:${PORT}`;\nconst { browser, page, cdp } = await moTrinhDuyet({ inConsole: false, context: { timezoneId: 'Asia/Ho_Chi_Minh', locale: 'vi-VN' } });\nawait cdp.send('Network.enable');\nconst yc = new Map();\ncdp.on('Network.requestWillBeSent', (e) =&gt; {\n  if (!e.request.url.includes('/api/') &amp;&amp; e.type !== 'Document') return;\n  if (e.redirectResponse) console.log(`   ${yc.get(e.requestId).method.padEnd(5)} ${yc.get(e.requestId).path}  → ${e.redirectResponse.status}  Location: ${e.redirectResponse.headers.Location || e.redirectResponse.headers.location}`);\n  const u = new URL(e.request.url);\n  yc.set(e.requestId, { method: e.request.method, path: u.pathname, ct: e.request.headers['Content-Type'], body: e.request.postData });\n});\ncdp.on('Network.requestWillBeSentExtraInfo', (e) =&gt; { const c = e.headers.Cookie || e.headers.cookie; if (c &amp;&amp; yc.has(e.requestId)) yc.get(e.requestId).cookie = c.length; });\ncdp.on('Network.responseReceived', (e) =&gt; {\n  const r = yc.get(e.requestId); if (!r) return;\n  console.log(`   ${r.method.padEnd(5)} ${r.path}  → ${e.response.status}` + (r.ct ? `   ▸ Content-Type: ${r.ct}` : '') + (r.body ? `   ▸ body: ${r.body}` : '') + (r.cookie ? `   ▸ Cookie: ${r.cookie} byte` : ''));\n});\nconst thongBao = async () =&gt; (await page.textContent('#tb')).trim();\nconst ketQua = {};\n\nconsole.log(`## BUG-601 + BUG-602: đặt lượt Lab 401, 26/11/2026 08:00`);\nawait page.goto(GOC); await page.waitForSelector('#ds li');\nawait page.click('#form button'); await ngu(600);\nconst tb1 = await thongBao(); console.log(`   giao diện: \"${tb1}\"`);\nketQua['BUG-601'] = tb1.startsWith('Đã đặt');\nconst dong = ketQua['BUG-601'] ? (await page.textContent('#ds li:last-child')).trim() : '';\nif (dong) console.log(`   dòng mới trong lịch: \"${dong.replace(/\\s+Ghi chú.*/, '')}\"`);\nketQua['BUG-602'] = /08:00:00 26\\/11\\/2026/.test(dong);\n\nconsole.log(`## BUG-603: ghi chú \"mang theo laptop\" cho lượt #1`);\npage.once('dialog', (d) =&gt; d.accept('mang theo laptop'));\nawait page.click('#ds li[data-id=\"1\"] .gc'); await ngu(600);\nconsole.log(`   giao diện: \"${await thongBao()}\"`);\nconst ghi = (await page.textContent('#ds li[data-id=\"1\"] .ghi')).trim();\nconsole.log(`   ghi chú hiện trong lịch: \"${ghi}\"`);\nketQua['BUG-603'] = ghi === 'mang theo laptop';\n\nconsole.log(`## BUG-604: người dùng đã mở trang 160 lần trong 3 tháng`);\nfor (let i = 0; i &lt; 159; i++) await page.evaluate(() =&gt; ghiLuotXem());\nawait page.reload(); await ngu(400);\nconst tieuDe = await page.title(); const than = (await page.textContent('body')).trim().split('\\n')[0];\nconsole.log(`   tiêu đề trang: \"${tieuDe}\" — \"${than.slice(0, 60)}\"`);\nketQua['BUG-604'] = tieuDe.startsWith('LabFlow');\n\nconsole.log('## Kết quả');\nfor (const [k, v] of Object.entries(ketQua)) console.log(`   ${k}: ${v ? 'ĐẠT' : 'CHƯA'}`);\nawait browser.close();";
export const L_NANG_CAP = "// lab6-nang-cap.mjs — người dùng CŨ đã mang 160 cookie _lf_v* (≈ 9,6 KB) mở bản đã sửa: trang có mở được, cookie có được dọn không?\nimport { moTrinhDuyet, ngu } from './mo.mjs';\nconst GOC = `http://localhost:${process.argv[2] || 41620}`;\nconst { browser, ctx, page, cdp } = await moTrinhDuyet({ inConsole: false, context: { timezoneId: 'Asia/Ho_Chi_Minh' } });\nawait ctx.addCookies(Array.from({ length: 160 }, (_, i) =&gt; ({ name: `_lf_v${i + 1}`, value: `1795472665806.${crypto.randomUUID()}`, url: GOC })));\nawait cdp.send('Network.enable');\nconst yc = new Map();\ncdp.on('Network.requestWillBeSent', (e) =&gt; yc.set(e.requestId, new URL(e.request.url).pathname));\ncdp.on('Network.requestWillBeSentExtraInfo', (e) =&gt; { yc.set(e.requestId + 'c', (e.headers.Cookie || '').length); });\ncdp.on('Network.responseReceived', (e) =&gt; { const p = yc.get(e.requestId); if (p === '/' || p === '/api/dat-cho') console.log(`   GET ${p} → ${e.response.status}   ▸ Cookie: ${yc.get(e.requestId + 'c') ?? 0} byte`); });\nconsole.log('## lần mở đầu tiên sau khi deploy bản sửa'); await page.goto(GOC); await ngu(500);\nconsole.log(`   cookie _lf_v* còn lại: ${(await ctx.cookies()).filter((c) =&gt; c.name.startsWith('_lf_v')).length}`);\nconsole.log('## lần mở thứ hai'); await page.reload(); await ngu(500);\nawait browser.close();";
export const MO = "// mo.mjs — mở Chrome thật (google-chrome 150, headless) qua Playwright + phiên CDP (cùng giao thức DevTools dùng).\n// In sự kiện theo kiểu bảng Console của DevTools; tra source map Vite để ra dòng .jsx gốc như DevTools hiện.\nimport { chromium } from 'playwright-core';\nimport { SourceMap } from 'node:module';\n\nconst maps = new Map();\nexport async function traMap(url, line, col) {            // line/col tính từ 0 (CDP)\n  if (!url || !/^http:\\/\\/localhost:416\\d\\d\\//.test(url)) return null;\n  if (!maps.has(url)) {\n    const src = await (await fetch(url)).text();\n    const b64 = src.match(/sourceMappingURL=data:application\\/json;(?:charset=utf-8;)?base64,([A-Za-z0-9+/=]+)/)?.[1];\n    maps.set(url, b64 ? new SourceMap(JSON.parse(Buffer.from(b64, 'base64').toString())) : null);\n  }\n  const sm = maps.get(url); if (!sm) return null;\n  const e = sm.findEntry(line, col);\n  return e &amp;&amp; e.originalSource ? `${e.originalSource.split('/').pop().split('?')[0]}:${e.originalLine + 1}` : null;\n}\nexport async function viTri(url, line, col) {\n  return (await traMap(url, line, col)) ?? `${(url || '?').split('/').pop().split('?')[0]}:${line + 1}`;\n}\n\nexport async function moTrinhDuyet({ inConsole = true, context = {} } = {}) {\n  const browser = await chromium.launch({ channel: 'chrome', headless: true, args: ['--no-first-run'] });\n  const ctx = await browser.newContext(context);\n  const page = await ctx.newPage();\n  const cdp = await ctx.newCDPSession(page);\n  const t0 = Date.now();\n  const nhan = () =&gt; `+${String(Date.now() - t0).padStart(5)}ms`;\n  if (inConsole) {\n    await cdp.send('Runtime.enable'); await cdp.send('Log.enable');\n    cdp.on('Runtime.consoleAPICalled', async (p) =&gt; {\n      const f = p.stackTrace?.callFrames?.[0];\n      const noi = f ? await viTri(f.url, f.lineNumber, f.columnNumber) : '';\n      const v = p.args.map((a) =&gt; a.value ?? a.description ?? a.preview?.description ?? a.type);\n      let chu = String(v[0]); let k = 1;\n      if (typeof v[0] === 'string' &amp;&amp; /%[sdoOc]/.test(v[0])) chu = v[0].replace(/%([sdoOc])/g, (_, t) =&gt; (t === 'c' ? (k++, '') : String(v[k++])));\n      chu = [chu, ...v.slice(k)].join(' ');\n      console.log(`${nhan()} [console.${p.type}] ${chu.split('\\n').slice(0, Number(process.env.DONG || 1)).join('\\n      ')}   ${noi}`);\n    });\n    cdp.on('Runtime.exceptionThrown', async (p) =&gt; {\n      const d = p.exceptionDetails; const f = d.stackTrace?.callFrames?.[0];\n      const noi = f ? await viTri(f.url, f.lineNumber, f.columnNumber) : await viTri(d.url, d.lineNumber, d.columnNumber);\n      console.log(`${nhan()} [Uncaught] ${(d.exception?.description || d.text).split('\\n')[0]}   ${noi}`);\n      for (const c of (d.stackTrace?.callFrames || []).slice(0, Number(process.env.SAU || 0))) console.log(`             at ${c.functionName || '(ẩn danh)'} (${await viTri(c.url, c.lineNumber, c.columnNumber)})`);\n    });\n    cdp.on('Log.entryAdded', ({ entry: e }) =&gt; console.log(`${nhan()} [${e.source}/${e.level}] ${e.text}${e.url ? '  ' + e.url : ''}`));\n  }\n  return { browser, ctx, page, cdp, nhan };\n}\nexport const ngu = (ms) =&gt; new Promise((r) =&gt; setTimeout(r, ms));";
export const BRU_ENV = "vars {\n  baseUrl: http://127.0.0.1:41610\n  token: {{process.env.LABFLOW_TOKEN}}\n}";
export const BRU_TOI = "meta {\n  name: Tôi là ai\n  type: http\n  seq: 2\n}\n\nget {\n  url: {{baseUrl}}/api/toi\n  body: none\n  auth: bearer\n}\n\nauth:bearer {\n  token: {{token}}\n}\n\nassert {\n  res.status: eq 200\n  res.body.vaiTro: eq SV\n}";
